insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 1, 'Why does a drilling engineer answer the question of duration before answering the question of money?', '["Unit rates are fixed inside a tender and cannot be argued over.", "Because a finance department will only release an authorisation for expenditure after a firm calendar date has been agreed with it.", "Almost every resource on a well is hired by the day, so the day count drags the money along behind it.", "Because tangible items such as casing and the wellhead dominate the base estimate."]'::jsonb, 2, 'Care over unit rates cannot rescue an estimate whose day count was wrong from the start.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 2, 'On the golden programme, what does one extra day of elapsed time add to the cost of the well?', '["It adds 160,000 dollars, being a rig dayrate of 100,000 plus an integrated services spread of 60,000.", "It adds 100,000 dollars, which is the contracted rig dayrate.", "It adds nothing at all, because the extra day is already covered by the contingency provision that sits on top of the base estimate.", "It adds 298,888 dollars, the base estimate spread evenly across eighteen days."]'::jsonb, 0, 'The figure is not an approximation, because both rates are contracted before the well is spudded.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 3, 'What share of the 5,380,000 dollar base estimate is exposed directly to the number of days on the well?', '["Around 19.5 percent, matching the tangible share of the authorisation for expenditure.", "About 38.1 percent, which is the part of the base carried by the lump sum items in the cost list.", "Ten percent, which is the contingency fraction applied to the base estimate once the schedule has been rolled up and agreed.", "It is 53.53 percent, the largest single block in the estimate and the one the calendar moves."]'::jsonb, 3, 'Eighteen days at 160,000 dollars per day is 2,880,000 dollars of a 5,380,000 dollar base.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 4, 'How does the engine convert the total elapsed hours of the golden case into a figure in days?', '["It divides the elapsed hours by a working day of twelve rig hours.", "It divides 432 elapsed hours by a fixed 24 hours per day, which gives exactly 18 days on the rig.", "It counts only the hours in which the bit is actually turning and reports those rotating hours as the day count for the well.", "It rounds the elapsed hours up to the next whole tour before dividing."]'::jsonb, 1, 'The engine holds 24 hours per day as a constant, so a rig day and a calendar day are the same thing here.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 5, 'How does the non-productive time allowance turn the productive hours of the golden case into elapsed hours?', '["Each productive duration is multiplied by one plus 0.125, so 384 hours becomes 432 and 48 hours are added.", "A flat block of 48 hours is appended to the end of the programme.", "The allowance is deducted from the rotating hours of the three drill activities and then redistributed over the other seven activities in the list.", "It multiplies only the flat activities, leaving the drill and trip durations untouched."]'::jsonb, 0, 'Because the allowance is a stretch, it scales with every activity rather than sitting in one place.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 6, 'What does the authorisation for expenditure produced on the golden case contain?', '["A single undivided base figure of 5,918,000 dollars.", "A per-metre unit price of 770 dollars applied across the full 3,000 m of hole that the programme reaches at total depth.", "A tangible figure of 1,050,000 dollars, an intangible figure of 4,330,000 and a base of 5,380,000 dollars.", "A tangible figure of 4,330,000 dollars against an intangible figure of 1,050,000."]'::jsonb, 2, 'A contingency of 538,000 dollars at a fraction of 0.1 lifts that base to a total of 5,918,000 dollars.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 7, 'Where does the final point of the cost-time curve land on the golden case?', '["On the 5,918,000 dollar total, since the curve accrues contingency too.", "Exactly on the 5,380,000 dollar base cost, with an absolute error of zero against the priced estimate.", "Slightly below the base cost, because the curve stops accruing money at the last activity boundary rather than at the moment the rig is released.", "On a value that depends on how finely the elapsed hours were sampled."]'::jsonb, 1, 'The curve is an accrual of the same base along the schedule, so it can only end where the base is.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 8, 'What is the correct standing of the 770 dollars per metre figure that ships with the engine?', '["It is the unit price the engine applies to every metre of the golden hole.", "It is a benchmark rate for a 3,000 m offshore shelf well drilled on the Gulf of Mexico shelf, flagged as indicative only.", "It is the production hole cost divided by the 1,000 m that section drills.", "It is a standalone worked example whose 16 hour trip matches no trip anywhere in the golden programme."]'::jsonb, 3, 'Its inputs are a 1,000 m interval, 100 drilling hours, 4 connection hours, a 50,000 dollar bit and a 6,000 dollar hourly rig rate.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 9, 'Why does the sampling for a risked run sit outside the deterministic evaluator rather than inside it?', '["Keeping the sampler outside means every published percentile can be reproduced from the same stated inputs.", "Because the evaluator is too slow to be called more than once.", "Because the engine has no way of representing a triangular distribution on a rate of penetration and therefore has to be handed sampled values.", "Because a risked result is reported in metres rather than in hours."]'::jsonb, 0, 'The evaluator itself stays deterministic, so a risked run is just that same arithmetic called many times over.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 10, 'What does the engine assume about the rate of penetration you enter for a drill activity?', '["That it was derived from the mud weight and the annular velocity.", "That you have already accounted for hole cleaning yourself, since it models no hydraulics of any kind.", "That it will be corrected internally once the equivalent circulating density and the pump rate for the section have been supplied to the engine.", "That it applies only until the first connection is made in the section."]'::jsonb, 1, 'Mud weight, pump rate and equivalent circulating density are absent from the model, so a slow hole means a slower rate you assert.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 11, 'How does the engine treat a long horizontal hole when it computes the duration of a trip?', '["It applies a drag multiplier once the inclination passes 60 degrees.", "It reads the string weight and the hole angle from the activity and lengthens the trip in proportion to the resulting hook load at the surface.", "Identically to a vertical hole, because there is no string model and no torque or drag anywhere in it.", "It refuses the activity and asks for a survey listing before proceeding."]'::jsonb, 2, 'A hole that will be slow to trip is expressed by entering a slower trip speed, not by any geometry the engine reads.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 12, 'What will the engine do if you ask whether moving a casing point would shorten the well?', '["It searches the neighbouring casing depths and returns the cheapest of them.", "It reorders the activity list automatically so that the fastest feasible sequence is evaluated in place of the one that was written.", "It reports the answer from its indicative regional benchmark.", "Nothing, because it carries no optimiser, so you build the other programme and evaluate that one too."]'::jsonb, 3, 'The engine evaluates the order you wrote and nothing else, which is what makes two programmes comparable.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 13, 'What standing do the suggested day counts and rates from the regional benchmark carry?', '["They are flagged indicative and serve as a sanity check, so they are never a price for the well.", "They are contracted rates the engine applies unless you override them.", "They are the rates used to build the golden case, which is why that programme reaches a base estimate of 5,380,000 dollars.", "They are audited historical averages that the engine requires you to justify."]'::jsonb, 0, 'For a 3,000 m offshore shelf well in the Gulf of Mexico the suggestion is 8 best-in-class days and 9 dry hole days.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 14, 'Why is the time-depth curve of the golden well a staircase rather than a single sloped line?', '["Because depth is recorded once per day rather than continuously.", "Because the non-productive allowance is applied in whole blocks between sections, which introduces a vertical step at each casing point in the well.", "Every activity consumes hours but only a drill activity makes hole, so the curve goes flat elsewhere.", "Because the curve plots true vertical depth against measured depth."]'::jsonb, 2, 'Between hour 324 and hour 432 the hole does not deepen at all, which is 108 elapsed hours of a flat tread.'),
  ('wellcost', 'beginner', 'module', 'm01-what-this-course-decides', 15, 'What goes wrong when metres per rotating hour is quoted where a schedule number was wanted?', '["Nothing, because the two readings agree once rounded to whole metres.", "The well is understated by roughly half, since 13.64 against 6.94 metres per hour are different readings.", "The estimate is overstated, because rotating hours already carry the non-productive allowance while the elapsed hours do not carry it at all.", "The drilled depth is overstated while the day count stays correct."]'::jsonb, 1, 'Metres per rotating hour belongs in a bit or bottomhole assembly review, not on the front of a cost estimate.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 1, 'What is the single unit from which a programme in this engine is built?', '["The hole section, each one closed by the casing string run into it.", "The activity, since there is no notion of a section, a phase or a run anywhere in the model.", "The bit run, which is opened when the string goes in the hole and closed when the bit is laid down on the pipe deck.", "The rig day, which the engine subdivides into productive and non-productive parts."]'::jsonb, 1, 'The engine walks that array once from front to back, carrying a running clock and a running hole depth.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 2, 'How large is the golden worked programme that this course returns to throughout?', '["Eight activities carrying 432 productive hours to a total depth of 3,000 m.", "Three activities, one for each hole section, carrying 220 rotating hours between them and reaching 3,000 m of hole.", "Eleven activities, one for each point plotted on the time-depth curve.", "Ten activities carrying 384 productive hours and making 3,000 m of hole in total."]'::jsonb, 3, 'The curve drawn from that walk has eleven points, one at spud and one at the end of each activity.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 3, 'What happens to the rest of the schedule if ten hours are added to the surface hole activity?', '["Everything below it moves ten hours later, because each activity starts where the one above it ended.", "Only the surface hole row changes, as the others hold fixed dates.", "The completion activity absorbs the addition by shortening itself, so that the released total for the rig stays at eighteen days.", "The addition is spread evenly across the remaining nine activities."]'::jsonb, 0, 'That running clock is why the start and end hour of any row depend on every row above it.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 4, 'What does the engine do when a drill activity claims to begin at 2,000 m while the hole stands at 500 m?', '["It shifts the top depth down to meet the hole and carries on.", "It accepts the activity and records the gap as non-productive time so that the drilled metres total still agrees with the depth reached.", "It halts and raises an error that names both depths rather than inventing 1,500 m of hole nobody drilled.", "It reorders the list until the depths line up correctly."]'::jsonb, 2, 'That continuity check lives in the programme walk, not in the duration formula of the activity itself.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 5, 'What does the engine do with an activity whose kind is not one of the four it recognises?', '["It falls back to treating the activity as flat time of zero hours.", "It prices the activity from its label instead, matching the wording against the vocabulary of kinds that the engine exports.", "It warns you but evaluates the programme anyway.", "It raises an error naming the unknown kind, and the programme does not evaluate at all."]'::jsonb, 3, 'A closed list of kinds means no schedule can carry a duration whose provenance nobody is able to explain.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 6, 'Why is the measured depth doubled inside the formula for a trip?', '["Because the string has to be measured going in and again coming out.", "Because a trip in this engine is a round trip by definition, taken out of the hole and back in again.", "Because the trip speed quoted for the activity is a one way figure that has to be converted before the duration of the round trip can be found.", "Because a trip is always paired with the casing run that follows it."]'::jsonb, 1, 'There is no half trip kind, so a single leg is entered by halving the depth or by using a flat activity.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 7, 'How do the four kinds rank by productive hours across the golden programme?', '["Drilling leads on 220 hours, then flat time on 84, then casing on 60 and tripping last on 20.", "Casing leads on 60 hours, then drilling, then tripping, then flat time.", "Flat time leads on 84 hours, then tripping on 20, then casing on 60 and finally the three drill activities carrying the remainder.", "Tripping leads, since the two round trips are the deepest activities in the list."]'::jsonb, 0, 'The two round trips together take less time than the rig move and spud does on its own.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 8, 'Which property of an activity selects the arithmetic used to compute its duration?', '["The label, which the engine parses for words such as drill or trip.", "The identifier, which the engine reads as a sequence number and uses to decide where in the walk the activity belongs and how it is priced.", "The kind and nothing else, since the label is free text and the identifier only matters to cost items.", "The depth fields, from which the engine infers what sort of work is intended."]'::jsonb, 2, 'Cost items link to an activity by its identifier, which is why that field is not merely decorative.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 9, 'Which fields must a drill activity carry, and what must be true of them?', '["A top depth, a bottom depth and a rate of penetration, with the bottom deeper and the rate above zero.", "A depth and a rate of penetration, both of them at least zero.", "A top depth, a bottom depth, a rate of penetration and a flat term in hours, with every one of the four required to be strictly greater than zero.", "An interval in metres and a duration in hours, checked against each other."]'::jsonb, 0, 'Omit any required field and the engine names both the activity and the field rather than guessing a default.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 10, 'Which field on an activity may be left out, and how is it then treated?', '["The trip speed, which falls back to the run speed of the casing string above.", "The rate of penetration, which the engine infers from the interval and the elapsed hours already accumulated in the walk to that point.", "The label, which the engine replaces with the identifier.", "The casing flat term, which is taken as zero and reduces the job to a bare running calculation."]'::jsonb, 3, 'Every other field on every kind has to be present and finite before the programme will evaluate.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 11, 'Why may a casing run sit at zero depth while a drill activity may never have a zero interval?', '["Because zero depth is only permitted before the well has been spudded.", "Because a drill activity that does not deepen the hole is not a drill activity, whereas casing makes no hole.", "Because the engine measures a casing run from the shoe of the previous string, so its depth is a difference that is allowed to come out at nothing.", "Because a zero interval would divide by zero in the drilling form."]'::jsonb, 1, 'The rule is an asymmetry in the depth checks, not an accident of how the arithmetic happens to behave.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 12, 'How long would the 100 hour intermediate section take if it were moved to ninth place in the list?', '["Rather less, since the crew would be further down its learning curve.", "Rather more, since the trip and casing activities placed above it would have left the hole in a condition that the drilling form reads before evaluating.", "Exactly 100 productive hours still, because no activity in the model carries any interaction term.", "It cannot be computed, because a drill activity may not follow a casing run."]'::jsonb, 2, 'Each duration is evaluated from its own arguments alone, with no memory of what came before it.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 13, 'What does a flat activity read, and what does it deliberately ignore?', '["It reads one duration in hours and ignores depth and rate, because its time answers to neither of them.", "It reads a depth and a flat term, and ignores the rate of penetration.", "It reads a duration in hours together with the depth at which the work takes place, so that the time-depth curve can be drawn correctly through it.", "It reads nothing at all and takes its hours from the activity above."]'::jsonb, 0, 'Waiting on cement does not take twice as long at 3,000 m as at 1,500 m, so inventing a rate for it would model worse.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 14, 'How does planned flat time compare with tripping time across the golden programme?', '["The two are close, at 84 hours against 60 hours respectively.", "Flat time carries 84 hours against 20 hours of tripping, so it is more than four times the larger block.", "Tripping is much the heavier of the two once both round trips have been stretched by the non-productive allowance applied to them.", "Flat time is the smaller, since only the rig move is entered that way."]'::jsonb, 1, 'Flat time is the second largest block on the well, behind the rotating hours and ahead of casing.'),
  ('wellcost', 'beginner', 'module', 'm02-the-activity', 15, 'How is money attached to the golden programme, given that no activity carries a price?', '["Each activity carries a dayrate that the engine multiplies by its hours.", "The base estimate is divided across the ten activities in proportion to the elapsed hours each of them consumes on the schedule.", "A separate list of cost items points at the schedule, and a lump item names the activity it belongs to.", "Cost is attached to the hole sections rather than to individual activities."]'::jsonb, 2, 'The link runs one way only, so the same 18 day schedule can be repriced without a single duration changing.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 1, 'How does drilling time behave in the two arguments of its formula?', '["It is straight in both, so either argument may be traded against the other at a fixed exchange rate.", "It is hyperbolic in the interval and straight in the rate of penetration.", "It is straight in the interval and flat in the rate above about 20 metres per hour, where the curve has run out of room to fall any further.", "It is straight in the interval and a hyperbola in the rate of penetration."]'::jsonb, 3, 'Twice the metres is twice the hours, but twice the rate is only half the hours, and the two are not the same behaviour.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 2, 'What quantity stays fixed as the rate of penetration is swept across a section of fixed length?', '["The hours per thousand metres drilled through the section.", "The product of the rate and the hours, which holds at 1,500 across every row of a 1,500 m section.", "The ratio of the hours to the rate, which is what makes the relationship between the two a hyperbola rather than a straight line.", "The difference between the hours and the rate, once both are in consistent units."]'::jsonb, 1, 'An invariant product is the definition of a hyperbola, which is why the curve never touches either axis.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 3, 'A 1,500 m section is planned at 15 metres per hour. What happens if the rate turns out to be 5?', '["The hours rise by a third, from 100 to about 133.", "The hours double to 200, since the engine caps the penalty a single rate assumption is allowed to apply to one section.", "The hours triple from 100 to 300, because a third of the rate is exactly three times the duration.", "The hours rise to 187.5, which is the value the sweep gives at 8 metres per hour."]'::jsonb, 2, 'At 300 hours that one section alone has become 12.5 days of rig time.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 4, 'Why does schedule risk sit almost entirely on the slow side of a rate assumption?', '["Going from 30 to 40 metres per hour saves 12.5 hours, but falling from 10 to 5 costs a full 150.", "Because slow sections are drilled with more connections in them.", "Because the non-productive allowance is applied only to the hours above the planned duration, so a slow section is stretched twice over by it.", "Because a fast section still has to wait on the casing crew behind it."]'::jsonb, 0, 'The curve is steep on the slow side and nearly flat on the fast side, so optimism costs more than pessimism gains.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 5, 'What form does the engine use to compute the duration of a trip activity?', '["The measured depth divided by the trip speed, doubled only below 2,000 m.", "Twice the measured depth divided by the trip speed, with the factor of two fixed inside the formula.", "The measured depth divided by the trip speed and then multiplied by a factor that the engine reads from the hole angle and the string weight of the activity.", "The measured depth multiplied by the trip speed, in hours per thousand metres."]'::jsonb, 1, 'At a trip speed of 500 metres per hour that works out at 4 hours per thousand metres, at any depth.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 6, 'What should you do when the work you need to schedule is a single leg rather than a round trip?', '["Enter a trip speed of twice the real figure so the doubling cancels out.", "Enter the trip normally, since the engine detects a one way leg from the depth at which the previous activity in the list left the hole.", "Split the trip into two activities and delete the second.", "Halve the depth on the trip activity, or else put the leg in as a flat activity instead."]'::jsonb, 3, 'There is no half trip kind in the closed list, and the factor of two is not an argument you are given.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 7, 'How does the ratio of round trip hours to one way hours change as the hole gets deeper?', '["It creeps above two below about 3,000 m, as the string grows heavier.", "It falls slowly towards one, because the running speed out of the hole improves once the heavyweight string is above the rotary and the stands are stacked.", "It does not change at all, holding at exactly two from 500 m right through to 5,000 m of depth.", "It depends on the trip speed entered for the activity."]'::jsonb, 2, 'At 500 metres per hour the one way leg is 6 hours at 3,000 m and the round trip is 12.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 8, 'How does a trip compare with the running leg of a casing job at the same depth and speed?', '["The trip takes exactly twice as long, so 10 hours against 5 at 2,000 m and 400 metres per hour.", "The two are equal, since both move one string over the same distance.", "The casing job takes longer, because pipe is run more slowly than drillpipe is tripped and the engine holds a separate speed for each.", "The trip takes about half as long, since it makes no hole on the way."]'::jsonb, 0, 'The factor comes only from the round trip, and the casing job then adds its flat term on top of the running leg.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 9, 'What shape does the casing formula take?', '["A purely proportional one in the depth of the string being run.", "An affine one, being the depth over the run speed plus a constant flat term that no speed can touch.", "A hyperbolic one in the run speed alone, so that the duration of the job falls away towards zero as the crew runs the string faster.", "The same form as a trip, with the factor of two replaced by one."]'::jsonb, 1, 'It is the only kind that mixes a depth driven behaviour and a constant behaviour inside one line of arithmetic.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 10, 'At 2,000 m with a 19 hour flat term, how long does a casing job take at an absurd 5,000 metres per hour?', '["A little under 0.4 hours, since the flat term scales with the speed too.", "About 9.5 hours, since the flat term is halved once the running leg falls below one hour and the crew is no longer waiting on pipe.", "It still takes 19.4 hours, because the running leg has collapsed to 0.4 hours and the floor has not moved.", "Exactly 19 hours, as the running leg rounds away to nothing."]'::jsonb, 2, 'Speed buys only the part of the job above the floor, which at 100 metres per hour was 20 hours and here is a fraction of one.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 11, 'What work does the flat term on a casing activity actually stand for?', '["The cement job, the circulation, the landing, the wait on cement and the pressure test that follows.", "The time spent making up the string on the pipe deck before it is run.", "An allowance for non-productive time that would otherwise have to be carried by the programme wide fraction applied to every activity.", "The interval between the casing point and the shoe track of the string."]'::jsonb, 0, 'By the time that term reaches 11 hours against a 5 hour running leg it is already 0.6875 of the job.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 12, 'What does checking the engine against an independently written oracle establish?', '["That the durations agree to within a tolerance of one hour per activity.", "That the closed forms reproduce field records from wells of a comparable depth, which is what allows the durations to be defended to a partner.", "That the arithmetic converges after a small number of iterations.", "That the maximum absolute error is zero, across every duration, every end hour and every total."]'::jsonb, 3, 'The cost-time curve and the cost per metre reproduce to zero as well, which is what closed forms buy in place of physics.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 13, 'Besides reproducibility, what does evaluating a schedule from closed forms give you?', '["It lets the engine reorder the activity list to find a shorter well.", "It lets the engine carry a learning curve across a pad, so that the third identical section is evaluated faster than the first one was.", "It can be run backwards, so the rate needed to fit a section into four days is arithmetic and not a search.", "It allows a rate of penetration to vary continuously down a section."]'::jsonb, 2, 'Every hour also traces to one division with named arguments, which ends an argument about where a duration came from.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 14, 'How should a section that drills fast in sand and slow in shale be entered?', '["As two drill activities with their own rates, or as one blended rate, since a rate cannot vary within an activity.", "As one activity carrying the slower of the two rates, to stay conservative.", "As one activity with the faster rate, leaving the shale to be picked up by the non-productive time allowance that is applied on top of every productive duration.", "As a drill activity followed by a flat activity for the shale."]'::jsonb, 0, 'A closed form can see only its own arguments, and depth dependent hardness is not among them.'),
  ('wellcost', 'beginner', 'module', 'm03-the-closed-forms', 15, 'Where do connections, surveys and hole trouble belong, given that no duration formula has a term for them?', '["Inside the rate of penetration, which is why it is quoted as an average.", "In a flat activity when you can name them in advance, and in the allowance when you cannot.", "Inside the casing flat term, which is the one place in the programme where time that answers to no rate and no depth is permitted to sit.", "Nowhere, since the engine treats them as already covered by the closed forms."]'::jsonb, 1, 'The cost per metre formula does take connection hours as a separate argument, 4 against 100 drilling hours in its example, but no duration formula does.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 1, 'The golden programme reports 384 productive hours and 432 elapsed hours. Where do the 48 non-productive hours come from?', '["A list of logged trouble incidents is totalled for the well.", "A separate trouble rate is applied to each of the four activity kinds and the results are added across the ten rows.", "They are reported as the difference between the elapsed clock and the summed closed forms, and nothing else touches it.", "A fixed trouble figure is carried on every activity alongside its own stated duration."]'::jsonb, 2, 'Because the split is a reported subtraction, the engine never stores non-productive time against any individual activity.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 2, 'Once an allowance of 0.125 has been typed into a programme, how is that fraction applied?', '["It forms a stretch factor of one plus the fraction and multiplies every productive duration by it.", "It divides the productive total by one minus the entered fraction.", "It adds the fraction of the elapsed hours as a single extra block of trouble time at the end of the programme, after the last activity.", "It reduces each activity rate by the fraction so that the same work takes longer."]'::jsonb, 0, 'One fraction drives the whole programme here, so the engine models trouble as a uniform stretch rather than as a list of events.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 3, 'Why is a 12.5 percent allowance not 12.5 percent of the time the rig is on location?', '["The engine rounds the allowance down before applying it.", "The allowance is applied only to the drill activities, so the other kinds dilute it across the elapsed clock of the programme.", "Elapsed hours are measured on a rig calendar rather than on wall clock time.", "The elapsed clock contains the added hours too, so the trouble share of it is the fraction divided by one plus the fraction."]'::jsonb, 3, 'On the golden case 0.125 divided by 1.125 is exactly one ninth, so the allowance is 11.11 percent of elapsed time.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 4, 'An engineer wants trouble time to be half of the days the rig is on the well and types 0.5 into the allowance field. What happens?', '["The engine refuses the entry because 0.5 is above the permitted ceiling.", "The engine schedules 24 days while the intention needs 32, leaving the plan 8 days light before work starts.", "The engine schedules 32 days, since a fraction of 0.5 already splits the elapsed clock into two equal halves of work and trouble.", "The engine schedules 24 days, which is what the intention needed."]'::jsonb, 1, 'At a fraction of 0.5 the trouble time equals the working time yet still accounts for only a third of the elapsed clock.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 5, 'Sweeping the allowance from 0 to 0.5 across the golden programme, what does the productive hours column do?', '["It rises in proportion with the allowance being swept.", "It falls slightly, since more of the clock is reassigned from work to trouble as the allowance is raised step by step.", "It reads 384 at every step, because the stretch is applied after the closed forms and can never reach back into them.", "It rises to 576 hours at the top of the sweep."]'::jsonb, 2, 'An unchanging productive column proves the allowance has been applied to the right quantity, which is one of the two standard checks.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 6, 'A partner supplies an allowance already expressed as a share of the elapsed clock. How should that number be entered?', '["Divide the supplied share by one minus itself, because the field expects a stretch on productive time instead.", "Enter it unchanged, since both conventions give the same schedule.", "Multiply the supplied share by 24 first, so that it matches the hours per day constant the rollup divides by later on.", "Divide the supplied share by one plus itself before typing it in."]'::jsonb, 0, 'A quarter of elapsed time therefore needs a fraction of one third typed into the field.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 7, 'Which of these belongs in the non-productive bucket on a well estimate?', '["A round trip to change a bit that drilled its planned interval.", "Jarring on stuck pipe, because the hours advance the well by nothing at all while the spread stays on hire.", "A wiper trip that was written into the programme with a stated trip speed, which the closed form for tripping already prices.", "Cementing time carried as a flat activity with a stated duration."]'::jsonb, 1, 'Waiting on weather, waiting on a boat, fishing and sidetracks fill out the usual list on a daily drilling report.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 8, 'A section drills consistently below its planned rate of penetration. Where does that time belong?', '["In the allowance, alongside waiting on weather.", "Split evenly between the two buckets, because a slow section is partly a rate problem and partly an unforeseen hole problem.", "In a flat activity with the lost hours stated directly.", "In productive time at a lower rate, entered on the drill activity, since recording it as trouble hides the real cause."]'::jsonb, 3, 'Module 3 showed the hyperbola behind this: a third of the rate triples the hours on the same interval.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 9, 'The same wiper trip appears on two wells, once in the original programme and once run because the hole was packing off. How are the two treated?', '["Both are productive, since a trip has a closed form.", "Both are non-productive, because a wiper trip makes no hole and therefore buys no progress towards total depth at all.", "The planned one is productive time priced by the trip form, and the unplanned one belongs inside the trouble allowance.", "Both sit outside the model and are carried as a separate line."]'::jsonb, 2, 'The boundary is a judgement about why the hours were spent, not about what the activity was called.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 10, 'How can a sidetracked interval be carried in this engine?', '["Inside the allowance or as a flat activity with a stated duration, since the engine refuses to drill a redrilled interval.", "As a drill activity with the redrilled interval and its own rate.", "As a trip activity to the sidetrack depth, because the string travels that interval a second time on the way back in.", "As a casing activity with the flat term raised to absorb it."]'::jsonb, 0, 'The refusal is explicit: a drill activity must start exactly where the hole currently is, and the engine names both depths.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 11, 'Why does the boundary between the two buckets have to be written down beside the estimate?', '["Because the engine validates the boundary on evaluation.", "Because auditors require the definition to sit in the same file as the programme before an estimate can be issued for review.", "Because the boundary changes the productive hours the closed forms return.", "An allowance only means something against the offset wells it came from, and those wells drew the boundary somewhere."]'::jsonb, 3, 'If the offset set counted rig repair as trouble and yours does not, the allowance is already too low before a number is chosen.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 12, 'Grouping the golden programme''s 384 productive hours by kind gives drill 220, flat 84, casing 60 and trip 20. What does that show?', '["That the drill activities are the only rows worth reviewing.", "That 164 productive hours are work which has to happen and yet advances the well by not one metre of hole.", "That flat and casing work together take longer than the drilling does, so the bit accounts for a minority of the productive hours.", "That the three drill rows carry the whole of the allowance."]'::jsonb, 1, 'Halving every rotating hour would remove 110 hours from 384 and leave the other 164 exactly where they were.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 13, 'Drilling occupies 57.29 percent of the golden case''s 432 elapsed hours. What happens to that percentage when the allowance is changed?', '["It stays at 57.29 percent, because every activity is stretched by the same factor and so keeps its share of the total.", "It rises, since drill rows are stretched more than flat rows.", "It falls steadily as the allowance grows, because the added trouble hours are held outside the drill rows and dilute their share.", "It moves unpredictably, depending on the order of the activities."]'::jsonb, 0, 'Across the whole allowance sweep the maximum drift in those activity shares is exactly zero.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 14, 'Why are the productive and non-productive hours kept apart rather than merged into one schedule figure?', '["Because the engine cannot compute a single combined total.", "Because contracts price the two buckets at different day rates, so the split has to survive all the way through to the invoice.", "They are bought back by different means, one through rate and planning and the other through risk management.", "Because only productive hours are converted into days at the rollup."]'::jsonb, 2, 'Hole cleaning practice, mud design and casing points set above the trouble zone appear in no closed form at all.'),
  ('wellcost', 'beginner', 'module', 'm04-productive-and-non-productive', 15, 'A reviewer finds that an expected slow section has been carried by raising the allowance instead of lowering the rate. What is wrong with that?', '["Nothing, provided the elapsed days come out the same.", "It presents a technical rate problem as bad luck, and bad luck never earns a review of the bit programme.", "It breaks the engine, because an allowance above 0.3 is rejected and the schedule will not evaluate until the entry is reduced.", "It moves hours from the flat rows into the drill rows."]'::jsonb, 1, 'The mirror error is padding the rate to carry a trouble expectation, which makes an unstable hole read as a hard formation.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 1, 'How many unit conversions does the time side of the engine perform, and what are they?', '["Two, one for hours into days and one for metres into feet.", "Exactly one, a division of the elapsed hours by 24, applied once at the rollup and nowhere else in the model.", "Three, since the closed forms for drilling, tripping and running casing each return their own units before the rollup gathers them.", "None, because the activity durations are entered in days already."]'::jsonb, 1, 'Every closed form in the course returns hours, so the running clock and the allowance both work in hours throughout.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 2, 'Why does the rollup return elapsed days as a decimal rather than rounding to whole days?', '["Because contracts are billed in fractions of a day.", "Because the allowance fraction is itself a decimal, and the engine keeps every downstream figure at the precision of its smallest input.", "Because the engine cannot represent whole numbers in that field.", "Rounding would break the identity with the hour count and would hide real differences, since 16.8 and 17.6 are not the same rig slot."]'::jsonb, 3, 'Round only in the sentence written for a human, and say in that sentence that you have rounded.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 3, 'What kind of day does the constant of 24 hours represent?', '["A day of wall clock time, because a well already under way does not stop for the night or for a shift change.", "A working shift on the rig floor, net of handover.", "A rig calendar day, which excludes any period when the rig is on standby and therefore not earning progress on the well.", "A billing day as defined in the rig contract."]'::jsonb, 0, 'That choice is what lets the day count be multiplied straight into a rate per day on the cost side.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 4, 'The last row of the golden schedule ends at 432 hours and the reported elapsed total is also 432. Why do those two always agree?', '["The engine copies the reported total into the last row.", "The last activity is a flat one, and flat durations are stated rather than computed, so the engine can set it to close the gap.", "The clock is cumulative, so every row starts where the one above finished and the final end time is the total.", "The two agree only when the allowance is left at its default."]'::jsonb, 2, 'A disagreement between them means the programme has been edited and the totals were never recomputed.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 5, 'Which activity kinds move the drilled metres counter?', '["Drill and casing activities, since both are quoted in metres.", "Only drill activities, which add their interval and advance the hole depth to the new bottom of the well.", "All four kinds contribute, because each one records a start depth and an end depth on its row of the finished schedule.", "Drill and trip activities, because the string covers the interval in both."]'::jsonb, 1, 'Trips, casing runs and flat rows record a start depth equal to their end depth, so the drilled total passes straight through them.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 6, 'The golden programme includes round trips at 2,000 m and at 3,000 m. What do those depths contribute to the drilled total?', '["They add 5,000 m, since both figures are quoted in metres.", "They add 2,500 m, being half of the two depths, because the counter records only the outward leg of each round trip that is run.", "They add 3,000 m, taking the deeper of the two trips.", "Nothing at all, because the metres on a trip are travelled rather than made, and only new hole is counted."]'::jsonb, 3, 'Casing runs to 500 m, 2,000 m and 3,000 m are quoted in metres for the same reason and count for nothing either.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 7, 'Which figures sum to the golden programme''s drilled total of 3,000 m?', '["The three hole sections, 500 m of 26 inch, 1,500 m of 17.5 inch and 1,000 m of 12.25 inch, added in order.", "The final depth of each of the three casing strings run.", "The two trip depths plus the surface hole, since those are the three depth figures the programme states in metres for its activities.", "The deepest drill activity, extended to the reported total depth."]'::jsonb, 0, 'Each drill row gains the interval between its start depth and its end depth, so the intervals and not the depths are what add up.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 8, 'Drilled metres and total depth both read 3,000 m here. Why do they agree?', '["The engine copies total depth into the drilled counter.", "Casing is run to the same depth as the deepest hole section, and the engine takes the shallower of the two counters when it reports.", "A drill activity must begin exactly where the hole is, so a redrilled interval cannot be entered and the two can never part.", "Every activity in this particular programme happens to make hole."]'::jsonb, 2, 'Treat the agreement as a property of what the model refuses to represent, since on a real well with a sidetrack the two separate.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 9, 'Deepening the golden well''s production hole by 200 m, 500 m, 1,000 m and 1,500 m gives which pattern?', '["Only the depth column moves, while drilled metres holds at 3,000.", "Totals of 3,200, 3,500, 4,000 and 4,500 m appearing in the drilled column and the depth column alike.", "Both columns move, but the drilled figure lags because the added interval is charged against the deeper section only once the casing is run.", "Only the drilled column moves, while total depth holds at 3,000."]'::jsonb, 1, 'The extra interval also lengthens the schedule, since the deepest section is drilled at 10 metres per hour.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 10, 'Sweeping the allowance takes elapsed days from 16 to 24. What happens to drilled metres over that sweep?', '["It holds at 3,000 m throughout, which is why the two currencies of the rollup are described as independent.", "It rises with the days, since more hours on the well means more hole.", "It falls slightly, because the added trouble hours displace rotating hours from the three drill rows as the allowance is raised.", "It cannot be read while the allowance is being changed."]'::jsonb, 0, 'Changing a rate of penetration moves the days as well and leaves the drilled total at 3,000 for the same reason.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 11, 'Sorted by duration, the golden schedule''s top rows are 112.5 hours, 112.5 hours and 67.5 hours. What does that tell a reviewer?', '["That the schedule has been overwritten by hand somewhere.", "That the two deep sections were drilled at the same rate of penetration, since their durations came out identical to the tenth of an hour.", "That the completion is the row most worth challenging.", "That three rows out of ten hold most of the 432 hours, so reading the top of the sorted list finds the big numbers first."]'::jsonb, 3, 'The two matching rows are the intermediate and production hole sections, at 100 productive hours each before the stretch.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 12, 'A reviewer takes the ratio of duration to productive hours on three different rows of one schedule. What must be true?', '["The ratio must rise down the schedule as the clock accumulates.", "The ratio must be highest on the drill rows, since trouble time attaches to the making of hole rather than to any of the other kinds.", "All three ratios must be identical, because the allowance is a single uniform stretch applied to every row alike.", "The ratio must equal 24 on every row of the programme."]'::jsonb, 2, 'A row where the ratio differs is a row somebody has typed over, which is exactly what this check is for.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 13, 'Why do the flat rows deserve a question even when the schedule adds up?', '["Because flat rows carry no depth and so break the depth chain.", "Their durations are stated rather than computed, so they are the only numbers in the schedule no formula defends.", "Because a flat row is stretched by a different factor from the other kinds, which makes its contribution to the elapsed clock hard to predict.", "Because the engine assigns flat rows a default duration."]'::jsonb, 1, 'The golden case states 24 hours for rig move and spud and 60 for completion and handover, and both invite the question of where they came from.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 14, 'Evaluating a programme returns six totals. How many of them reach the cost side of the engine?', '["Two, the elapsed days and the drilled metres, which are the only quantities a cost line can be multiplied by.", "Four, everything except the two depth figures reported.", "All six, because the cost rollup reads the whole evaluated programme including the schedule rows and the productive split within it.", "Three, the elapsed days, the drilled metres and the total depth."]'::jsonb, 0, 'There are three cost bases and no fourth, so a per-day count and a per-metre count are sufficient to price the programme.'),
  ('wellcost', 'beginner', 'module', 'm05-rolling-up-a-programme', 15, 'What is lost when a schedule crosses into the cost rollup?', '["Nothing is lost, since the rollup passes the whole case document.", "The drilled metres are lost, because a per-metre line reads the depth of the deepest hole section directly from the programme instead.", "The allowance fraction is lost, but the split itself survives.", "The productive and non-productive split, along with the schedule rows and total depth, leaving one day count behind."]'::jsonb, 3, 'That is why the split is worth quoting beside the day count, since 18 days on its own cannot be challenged usefully.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Priya is labelling a handed-over programme line by line. One line gives a start depth, a bottom depth and a rate of penetration. What has she found?', '["A casing activity, which needs a depth and a running speed.", "A drill activity, whose productive hours she will get by dividing the interval between the two depths by the rate.", "A trip activity, since a start depth and a bottom depth together describe the string travelling from one to the other and back again.", "A flat activity, because two depths and a rate cannot be reduced to hours."]'::jsonb, 1, 'Step one of the capstone method labels every line before any arithmetic is done, and nothing else matters at that stage.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 2, 'A programme line is titled Displacement and logging suite, yet all it carries is a stated number of hours. How should the classification go?', '["It is a trip, since logging tools travel the hole.", "It has to be sent back to the originator, because a line whose title names two separate operations cannot be classified as a single activity.", "It is a casing run without its running speed filled in.", "It is flat work, because the label follows the fields a line is given rather than the name somebody typed above it."]'::jsonb, 3, 'Reading titles instead of fields is how a stated duration ends up being recomputed against a formula it was never meant for.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Sanjay reaches a line in a tender programme that no closed form can price. How should he carry it?', '["Carry it as flat work with a stated duration, or fold it into the allowance, rather than forcing it into a formula.", "Leave the line out and note the omission in the estimate.", "Reshape the line until it fits the nearest of the four kinds, since every activity in the engine has to arrive at its hours through one of them.", "Split it across the drill activities in proportion to their hours."]'::jsonb, 0, 'Forcing a line into the wrong kind produces a duration whose provenance nobody downstream can explain.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Tunde reviews a colleague''s schedule and finds the round trip row has come out at half the hours he expected. What has most likely happened?', '["The trip speed was entered in metres per day by mistake.", "The row was stretched by the allowance twice over, which halves it against a schedule where the stretch has been applied only once.", "The factor of two was left out, so only one leg of the journey has been priced instead of the string going down and back.", "The trip was placed before the drill activity that it follows."]'::jsonb, 2, 'A trip is a round trip by definition in this engine, which is why the depth is doubled inside the formula itself.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 5, 'An estimator prices a casing run from its depth and running speed alone and leaves the flat term empty. What does the review comment say?', '["Nothing, since the flat term applies only to liners.", "Most of the activity has been lost, because at realistic running speeds the flat term is the larger part of the job.", "The run is now too long, because the flat term is a credit against the running time rather than an addition to it, and omitting it inflates the row.", "The depth will no longer count towards drilled metres."]'::jsonb, 1, 'No running speed can touch the flat term, so it is the floor beneath the activity however fast the string goes in.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 6, 'A junior engineer applies a trouble allowance by dividing the productive hours by one minus the fraction. What should the reviewer say?', '["The arithmetic is right but should be done on days.", "The arithmetic is right for the totals, though it has to be repeated on every individual row before the schedule rows will accumulate correctly.", "The division is right, but it belongs after the conversion into days.", "The fraction is a stretch, so the productive hours are multiplied by one plus it and by nothing else."]'::jsonb, 3, 'Dividing by one minus the fraction is the conversion used the other way round, when a share of elapsed time has to be turned into a stretch.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Before issuing an estimate, an engineer recomputes it at the stated allowance, at zero and at double. What is she checking?', '["That the productive total is identical in all three runs, since anything else means the stretch reached a quantity it should not.", "That the elapsed days rise smoothly across the three runs.", "That the drilled metres change with the allowance, which is the sign that the stretch has been carried through the depth chain as well as the clock.", "That the schedule rows keep their order under all three."]'::jsonb, 0, 'This check takes seconds and it catches the single most common misunderstanding of the whole tier.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 8, 'A reviewer finds a schedule where the non-productive share of elapsed time comes out exactly equal to the allowance fraction entered. What does that reveal?', '["The programme contains only flat activities.", "The allowance was entered as a percentage rather than as a decimal fraction, which makes the two figures agree by coincidence at that scale.", "The trouble hours have been divided by the productive hours rather than by the elapsed hours, so the share is overstated.", "The schedule is correct, since the two are equal by definition."]'::jsonb, 2, 'The share of elapsed is strictly below the fraction at every allowance above zero, never equal to it.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 9, 'A colleague circulates a schedule quoting only the elapsed day count. What should the review ask him to add?', '["The drilled metres, which the day count conceals.", "The two hour figures behind it, since a day count on its own gives nobody anything they can usefully challenge.", "The rate of penetration used on each drill activity, because those are the only inputs in the whole schedule that a reviewer is able to dispute.", "The rig dayrate, so the number can be read as money."]'::jsonb, 1, 'The two hour figures point at different people, one at rate and planning and the other at risk management.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 10, 'A new starter asks what the whole Associate tier amounts to in one sentence. What is the answer?', '["Every number in it is an hour, and every hour is either bought with rate and planning or lost to trouble.", "Every number in it is a cost with the currency symbol removed.", "Every number in it is a depth, because a well estimate is built from the casing programme upwards and the clock is derived from the depths.", "Every number in it is an average taken across offset wells."]'::jsonb, 0, 'The tier deliberately prices nothing, so the ledger of where the days go is assembled before anybody argues about a rate sheet.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Having classified the activities and applied the allowance by hand, what remains for the last step of the method?', '["Add a rounding allowance to the day figure before quoting it.", "Convert the metres into days using the average rate of penetration, so that a single quantity carries the whole of the estimate forward.", "Total the depths reached by each activity in the programme.", "Divide the elapsed hours by 24 for days, add the drill intervals alone for metres, and keep both as decimals."]'::jsonb, 3, 'Only drill activities contribute intervals, which is why three of the four kinds add nothing at this step.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 12, 'A cost engineer picks up the golden programme to price it. Which numbers does the schedule owe her?', '["The productive hours and the non-productive hours.", "The full schedule with its start and end times, since a cost line has to be accrued against the activity it belongs to before it can be totalled.", "The elapsed days and the drilled metres, 18 and 3,000, which are the only two quantities her rate sheet can multiply.", "The total depth and the number of casing strings run."]'::jsonb, 2, 'There are exactly three cost bases and one of them multiplies nothing at all, so no third quantity is needed.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 13, 'A well runs longer than its estimate. Which lines on the authorisation for expenditure grow with the extra days?', '["Every line grows, in proportion to the overrun.", "Only the lines charged per day, whose sensitivity to elapsed days is 1.0 while the other two bases sit at zero.", "Only the per-metre lines grow, because a well that runs long is normally one that has drilled further than the programme allowed for.", "None of them, because the base estimate is fixed at sanction."]'::jsonb, 1, 'On the golden estimate 53.53 percent of the base is per-day exposed, so one extra day costs 160,000 dollars.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 14, 'The Professional tier shows contingency passing the largest real cost line at a fraction of 0.3346. Why is that worth knowing?', '["It shows a provision, which nobody has contracted for, outgrowing every line in the estimate that somebody has.", "It proves the contingency fraction has been set too high.", "It shows that contingency has to be spread back across the individual cost lines before an authorisation for expenditure can be issued to a partner.", "It shows the largest line has been priced on the wrong basis."]'::jsonb, 0, 'It passes the second largest line at a fraction of 0.2007, and neither figure is extreme in a frontier well.'),
  ('wellcost', 'beginner', 'module', 'm06-the-associate-reading', 15, 'An Associate is handed a drilling schedule she has never seen before. What can she now do with it?', '["Price it against a rate sheet and issue the estimate.", "Optimise the order of its activities, since the evaluator will search the alternatives once the programme has been entered correctly.", "Derive the rate of penetration each section will achieve.", "Check its two end identities, rank its rows, test its stretch and say which hours answer to rate and which to trouble."]'::jsonb, 3, 'None of that requires a single currency symbol, which is why the reading comes before the pricing rather than after it.'),
  ('wellcost', 'beginner', 'final', null, 1, 'An engineer finds a change that takes exactly one day of elapsed time off the golden well. Setting aside what the change itself costs, what has she saved?', '["160,000 dollars, being the 100,000 dollar rig dayrate plus the 60,000 dollar services spread for one day.", "5,380,000 dollars divided by 18, since the base is spread evenly.", "Nothing measurable until the rig releases, because the dayrate is contracted and cannot be reduced by finishing early.", "100,000 dollars, the rig dayrate, since the spread is billed against the well rather than against the day."]'::jsonb, 0, 'That exposure is 53.53 percent of the 5,380,000 dollar base and is the largest single block in the estimate.'),
  ('wellcost', 'beginner', 'final', null, 2, 'The mud engineer warns that hole cleaning will be marginal through the deepest section. The engine carries no hydraulics, so what does the estimator do?', '["Enter the planned mud weight so the engine can adjust the rate.", "Add a flat activity for circulating, and leave the rate of penetration untouched.", "Lower the rate of penetration asserted on that drill activity, because the rate is an input and not a result.", "Raise the non-productive allowance instead, since poor hole cleaning is trouble time and the drill rates should stay as planned."]'::jsonb, 2, 'Nothing in the model knows the pump rate, the annular velocity or the equivalent circulating density, so the physics arrives through the numbers you choose.'),
  ('wellcost', 'beginner', 'final', null, 3, 'Your programme evaluates at 18 days against a regional benchmark suggesting 8 best-in-class days for a 3,000 m offshore shelf well. What does that comparison settle?', '["That the programme is twice as long as it ought to be.", "Nothing by itself, because the benchmark is flagged indicative and serves as a sanity check on your own build.", "That the estimate must be rebuilt to the benchmark, because a suggested day count carries more weight than an unpriced activity list.", "That the benchmark rig rate of 450,000 dollars per day should replace your own."]'::jsonb, 1, 'The same suggestion carries 9 dry hole days and a 200,000 dollar per day spread, and every one of those figures is indicative rather than a price.'),
  ('wellcost', 'beginner', 'final', null, 4, 'A logistics planner needs to know when the completion crew should be on location. Which of the three published rates for the golden well feeds that date?', '["Metres per rotating hour, 13.64, the drilling performance figure.", "Any of the three, since all of them describe the same 3,000 m well.", "Metres per elapsed hour, 6.94, converted on a nine hour shift, since crews mobilise on shifts and not on wall clock days.", "Metres per elapsed day, 166.67, because a crew is booked against the calendar the well actually occupies."]'::jsonb, 3, 'The rotating figure belongs in a bit or bottomhole assembly review, and quoting it where a schedule number was wanted understates a well by roughly half.'),
  ('wellcost', 'beginner', 'final', null, 5, 'A tender response quotes 770 dollars per metre and attributes it to the 12.25in production hole of the published programme. Why does a reviewer strike that?', '["The figure comes from a standalone worked example whose 16 hour trip matches no trip in that programme.", "The figure is right but should be quoted for the whole well.", "The production hole is priced by the day rather than by the metre in this estimate.", "The figure was computed before the allowance was applied, so it needs stretching by one and one eighth before anyone quotes it."]'::jsonb, 0, 'In that example the rig takes 120 priced hours at 6,000 dollars an hour and the bit 50,000 dollars, which is where its 93.5 and 6.5 percent shares come from.'),
  ('wellcost', 'beginner', 'final', null, 6, 'Two offices run the same risked case on different machines and read identical percentiles. What makes the result repeatable?', '["The percentiles are cached alongside the published case.", "The engine iterates each activity until its duration converges, and convergence removes any dependence on the machine it ran on.", "The sampling sits outside the evaluator, which is deterministic and returns one answer for one set of inputs.", "The risked run uses a fixed number of iterations, and that alone fixes the answer."]'::jsonb, 2, 'Every duration here is a single division evaluated once, so a whole programme is a few dozen divisions and the evaluator can be called thousands of times.'),
  ('wellcost', 'beginner', 'final', null, 7, 'Between hour 324 and hour 432 the golden hole stands still at 3,000 m. Which work fills those 108 elapsed hours?', '["Waiting on cement, which the allowance covers.", "The round trip at total depth, the 9-5/8in casing job and the completion, none of which makes any hole.", "The deepest drill activity, still turning to bottom while the depth column waits to be updated at the end of the section.", "The rig move and spud, which is scheduled once total depth has been reached."]'::jsonb, 1, 'That standstill is a quarter of the elapsed clock, which is why the time depth curve reads as a staircase and not as one slope.'),
  ('wellcost', 'beginner', 'final', null, 8, 'The completion and handover row is dragged from the bottom of the activity list into the middle and the programme is evaluated again. What moves?', '["Nothing at all, because the clock is rebuilt from the totals.", "Every duration, since each activity is evaluated against the hole depth reached by the activities placed above it.", "The drilled metres total, because the completion no longer follows the deepest section.", "The start and end hours of every row below the move, while the 384 and 432 hour totals stay where they were."]'::jsonb, 3, 'There is no interaction term anywhere in the model, so an activity is worth the same hours wherever it sits in the queue.'),
  ('wellcost', 'beginner', 'final', null, 9, 'An engineer deletes the 17.5in intermediate hole to test a two string design and evaluates what is left. What comes back?', '["An error, because the production hole now claims to start at 2,000 m while the hole stands at 500 m.", "A schedule shorter by 112.5 hours and unchanged in depth.", "A warning that the drilled metres and the total depth no longer agree.", "A nine activity schedule in which the production hole quietly drills the missing interval too, because depth is carried forward."]'::jsonb, 0, 'The refusal names both depths rather than leaving 1,500 m of hole that nobody drilled.'),
  ('wellcost', 'beginner', 'final', null, 10, 'A handover sheet lists a casing job with a depth and a running speed, and the flat hours column has been left blank. Will it evaluate?', '["No, because casing needs all three of its fields.", "No, and the engine names the activity and the missing field before stopping.", "Yes, since the flat term is the one optional field, and leaving it out reduces the job to a bare running leg.", "Yes, and the flat term is borrowed from the nearest casing activity above it in the list so the job is not understated."]'::jsonb, 2, 'Every other field on every kind must be present and finite, and the engine will not guess a default for any of them.'),
  ('wellcost', 'beginner', 'final', null, 11, 'A blowout preventer test has to be scheduled after surface casing, and a colleague proposes trimming a rate of penetration to make room. What is the objection?', '["None, since both routes give the same elapsed days.", "Known rate independent work belongs in a flat activity, and padding a rate misstates why the hours are there.", "The test is a casing activity with a flat term, so trimming a rate would take hours out of the wrong part of the programme.", "A test cannot be scheduled until the casing job it follows has been priced."]'::jsonb, 1, 'Inflating a rate of penetration to make a schedule come out right is the usual sign that a flat activity was what you needed.'),
  ('wellcost', 'beginner', 'final', null, 12, 'The same 18 day programme is priced against a tender, then against a signed contract, and again once the well is over. What is rebuilt each time?', '["Only the cost list, because an activity carries a kind, a geometry and a rate, and never a price.", "The whole programme, since durations follow the rates paid.", "Nothing, since the authorisation for expenditure is stored with the programme it was priced from.", "The schedule, because a changed rate sheet changes the day count and therefore the start and end hours of every row."]'::jsonb, 0, 'The link runs one way, from a cost item to the activity it names, and an activity never points back at money.'),
  ('wellcost', 'beginner', 'final', null, 13, 'A crew insists that tripping is what eats a well. What does the golden programme''s own breakdown by kind say to that?', '["Tripping is second only to drilling at 84 hours.", "Tripping and casing together carry more hours than the three drill activities.", "Tripping cannot be compared with the other kinds, because the factor of two counts a round trip twice inside the productive column.", "Tripping is 20 of the 384 productive hours, less than the rig move alone, while drilling carries 220."]'::jsonb, 3, 'Flat work is the second largest block at 84 hours and casing carries 60, which leaves tripping the smallest thing on the list.'),
  ('wellcost', 'beginner', 'final', null, 14, 'An imported programme carries a line whose kind field reads ream. What happens on evaluation, and what is the honest fix?', '["The line is skipped and the totals come back short.", "The line is accepted, because the kind is free text used only in reports.", "Evaluation stops with an error naming the unknown kind, and the work is recast as flat hours or as allowance.", "An unrecognised kind is treated as flat and given whatever duration field can be found, so the totals still come out."]'::jsonb, 2, 'The vocabulary is a closed list on purpose, so that no schedule can hold a duration whose provenance nobody can explain.'),
  ('wellcost', 'beginner', 'final', null, 15, 'The 12.25in section was planned at 10 metres per hour over 1,000 m and the bit is making 5. What does the schedule now carry there?', '["200 productive hours in place of 100, and the extra 100 hours are stretched to 112.5 elapsed hours.", "150 productive hours, since the loss is shared with the allowance.", "100 productive hours still, with the shortfall carried as non-productive time.", "110 productive hours, because the rate enters through its logarithm and halving it is therefore a modest change."]'::jsonb, 0, 'Rate times hours is invariant at a fixed interval, so a third of the rate is exactly three times the hours.'),
  ('wellcost', 'beginner', 'final', null, 16, 'A full day has to come out of the golden schedule and only one change is permitted. Where is it worth looking?', '["At the round trips, which are the easiest rows to shorten.", "At the two 112.5 hour drill rows, since a day is 24 elapsed hours and nothing else on the list is big enough.", "At the 9-5/8in casing run, where lifting the speed from 300 metres per hour removes the longest running leg in the list.", "At the rig move, because a flat duration can be changed without touching any formula."]'::jsonb, 1, 'Deleting both round trips outright would free only 20 productive hours, which is short of a day even before the stretch is undone.'),
  ('wellcost', 'beginner', 'final', null, 17, 'Only a pull out of hole is needed at total depth and the string will stay at surface. What does the estimator enter?', '["A casing activity with no flat term, which runs one leg only.", "A trip at 3,000 m, and then halve the resulting hours by hand.", "Half the depth against the trip speed, or a flat activity of the hours, since the factor of two is fixed.", "A trip with the speed doubled, which cancels the factor of two and leaves the correct one way duration in the row."]'::jsonb, 2, 'There is no half trip kind in the engine, and the two lives inside the formula rather than in anybody''s judgement.'),
  ('wellcost', 'beginner', 'final', null, 18, 'A vendor offers a running tool that would double the speed on the 13-3/8in job at 2,000 m from 400 metres per hour. What does the programme gain?', '["Half the activity, so 24 hours becomes 12.", "Two and a half days, once the saving is stretched by the allowance and converted.", "Nothing at all, because a casing duration is entirely a flat term and the running speed is recorded only for reporting.", "Half of the 5 hour running leg, so the 24 hour activity becomes 21.5 and the 19 hour floor never moves."]'::jsonb, 3, 'At an absurd 5,000 metres per hour that same job still takes 19.4 hours, which is what a floor means.'),
  ('wellcost', 'beginner', 'final', null, 19, 'The production hole is split into two drill activities whose rates give the same 100 productive hours between them. What happens to the totals?', '["They do not change, because each activity is evaluated from its own arguments with no interaction anywhere.", "Elapsed hours fall, since two shorter rows stretch less.", "The schedule gains a row and the allowance is applied twice across that interval.", "The drilled metres total doubles, because both activities report the interval they cover and the counter adds each of them."]'::jsonb, 0, 'Splitting buys reporting granularity and nothing else, though it is the only way to show a formation that hardens partway down.'),
  ('wellcost', 'beginner', 'final', null, 20, 'A partner asks what rate of penetration would let the 17.5in section finish inside a stated number of days. How is that answered?', '["By sweeping rates in the panel until the days come out right.", "By reading the nearest row from the published rate sweep table.", "By running the division backwards, since a closed form inverts to arithmetic rather than needing any search.", "It cannot be answered directly, because the allowance couples that section to every other activity in the programme."]'::jsonb, 2, 'Invertibility is one of the four things a closed form buys, alongside reproducibility, speed and auditability.'),
  ('wellcost', 'beginner', 'final', null, 21, 'The cost per metre example counts 4 connection hours against 100 drilling hours, yet no duration formula has a connection term. How is that reconciled?', '["The rate of penetration already contains the connection time.", "That formula stands apart, and inside a programme connection time arrives as flat hours or through the allowance.", "Connection hours are subtracted from the drilling hours of a section before that section''s rate of penetration is applied to it.", "Connections count as tripping, since a stand is handled either way."]'::jsonb, 1, 'Surveys, unplanned bit changes, reaming and waiting have those same two homes, and there are only the two.'),
  ('wellcost', 'beginner', 'final', null, 22, 'A contractor quotes 20 elapsed days for a programme whose closed forms sum to 384 productive hours. What allowance is he carrying?', '["A fraction of 0.25, since 20 days is 480 hours and 480 over 384 is a stretch factor of one and a quarter.", "A fraction of 0.20, read off the day count against 16.", "A fraction of 0.0417, because the quoted days sit only 4 above the unstretched 16.", "It cannot be recovered from those two figures, because the stretch is applied row by row rather than to the productive total."]'::jsonb, 0, 'That allowance shows up as a fifth of the elapsed clock rather than a quarter, since 0.25 over 1.25 is 0.2.'),
  ('wellcost', 'beginner', 'final', null, 23, 'A client defines trouble time as a quarter of the hours the rig is on location. Which fraction goes into the allowance field?', '["A quarter, which is what the field means.", "Three quarters, since the productive part is what remains after the trouble.", "A fifth, because the field already expects a share of elapsed time and a quarter would then be counted twice over.", "One third, from a quarter divided by one minus a quarter, which delivers the intended 21.33 days."]'::jsonb, 3, 'Typing a quarter returns 480 hours and 20 days, so the shortfall against that intention is 1.33 days on this programme.'),
  ('wellcost', 'beginner', 'final', null, 24, 'Recomputing an estimate at the stated allowance, then at zero, then at double gives three different productive totals. What has gone wrong?', '["Nothing, because trouble time slows the work itself.", "The allowance was applied twice, once across the rows and once to the total.", "The stretch has been applied to the wrong quantity, since a closed form never sees the allowance at all.", "The three runs used different rates of penetration, which is the only input that can move a productive total between runs."]'::jsonb, 2, 'Across a published sweep from zero to 0.5 the productive column reads 384 at every step and the share each activity holds drifts by exactly zero.'),
  ('wellcost', 'beginner', 'final', null, 25, 'Somebody proposes halving every rotating hour on the golden well and expects the schedule to halve with it. What actually happens?', '["110 hours come out of the 384 productive hours, and the other 164 hours of trips, casing and flat work remain.", "Elapsed days fall from 18 to 9 exactly.", "Drilled metres fall in step with the hours, since both of them follow the drill rows.", "Nothing moves until the allowance is halved as well, because the stretch is applied to rotating hours before they are summed."]'::jsonb, 0, 'Drilling holds 57.29 percent of elapsed time at any allowance, so a bit can never buy back the remaining 42.71 percent.'),
  ('wellcost', 'beginner', 'final', null, 26, 'Your allowance came from offset wells that booked rig repair as trouble time, and your own convention excludes it. What follows?', '["Nothing, since the allowance is a single fraction either way.", "The allowance is too low before a number has even been chosen, because it was calibrated on a wider boundary.", "Only the elapsed day count is affected, and the productive hours would still reconcile against the offset wells they were drawn from.", "The allowance is too high, since rig repair already sits inside the flat rows."]'::jsonb, 1, 'Writing that boundary down beside the estimate is what makes 48 hours of allowance worth arguing about.'),
  ('wellcost', 'beginner', 'final', null, 27, 'A team reports that eight hours have come out of a schedule. Why does the reviewer insist on knowing which bucket they came from?', '["Because only productive hours are billed by the rig.", "Because drilled metres move with productive hours alone.", "Because one bucket answers to rate and planning and the other to risk management, which are different work.", "Because an hour saved inside the allowance is worth more than a productive one, the allowance being applied on top of everything else."]'::jsonb, 2, 'On the golden case 384 of the 432 hours answer to rate and planning and 48 answer to trouble, and no day count separates them.'),
  ('wellcost', 'beginner', 'final', null, 28, 'An estimator carries his expectation of trouble by quoting a rate below what the bit will really achieve. What does his estimate now claim?', '["That the well is shorter than the programme states.", "That the section will need two bit runs rather than one.", "That the allowance is zero, since the fraction is derived from the gap between a quoted rate and an achievable one.", "That the formation is hard, when what he meant was that the hole is unstable, and nobody downstream can tell."]'::jsonb, 3, 'The mirror failure is hiding a genuine rate problem inside the allowance, where it reads as bad luck and never earns a review of the bit programme.'),
  ('wellcost', 'beginner', 'final', null, 29, 'A reviewer has ten minutes with a schedule she has never seen before. Which two identities does she run first?', '["The last row''s end hour against the reported total, and the final depth against the drilled metres.", "The ratio of elapsed days to productive days on each row.", "The allowance fraction against the share of elapsed time it produces.", "The sum of the productive column against the sum of the duration column, which must agree once the allowance is removed."]'::jsonb, 0, 'Both checks take about ten seconds and both catch a programme that was edited and never evaluated again.'),
  ('wellcost', 'beginner', 'final', null, 30, 'Two options for one well come out at 16.8 and 17.6 days, and a manager wants both written as 17. What is lost?', '["Nothing, because a rig is booked in whole days.", "The allowance, which can no longer be recovered from a rounded day figure.", "A different rig slot in each case, along with the exact identity between the hours and the day count.", "The drilled metres, which are derived from the day count and therefore inherit whatever rounding is applied to it."]'::jsonb, 2, 'Carry the decimal all the way through and round only in the sentence written for a human, saying there that you have.'),
  ('wellcost', 'beginner', 'final', null, 31, 'On one schedule every row shows a duration of 1.125 times its productive hours except one. What does that single row tell you?', '["That row is non-productive time and carries no stretch.", "Somebody has overwritten it by hand, because one uniform stretch cannot produce two different ratios.", "That row belongs to a kind whose form returns elapsed hours directly, so the allowance is not applied to it twice over.", "The programme mixes two allowances, one for drilling and one for flat work."]'::jsonb, 1, 'The stretch is a single multiplication applied to every activity, which is why each of them keeps its exact share of the total.'),
  ('wellcost', 'beginner', 'final', null, 32, 'A review meeting opens by arguing about the production hole rate of penetration. Why is that a poor opening move?', '["The rate is fixed by the bit supplier and cannot be changed.", "Drilling is the smallest of the four kinds on a conventional well.", "Rates of penetration are the only inputs the engine derives for itself, so there is nothing in them for a meeting to decide.", "A guessed flat duration or a copied allowance will each shift the total further than any plausible rate argument."]'::jsonb, 3, 'A casing flat term left at a default belongs on that same list, since no formula defends a number somebody simply stated.'),
  ('wellcost', 'beginner', 'final', null, 33, 'The rig contract is written around a twelve hour working shift. Does the rollup constant change with it?', '["No, the divisor stays at 24 hours, because a well already under way does not stop when a shift ends.", "Yes, days are reported against whichever shift pattern is in use.", "No, though the day count is then doubled to give shift days.", "Yes, but only for the flat activities, since drilling and tripping run across shifts while flat work does not."]'::jsonb, 0, 'That single division is the one unit conversion the time side of the engine performs anywhere.'),
  ('wellcost', 'beginner', 'final', null, 34, 'Of the six totals the rollup reports, which one does a mud and consumables line read, and which one does the rig dayrate read?', '["Total depth and elapsed hours, taken from the last row.", "Drilled metres and productive hours, because trouble time is not billable.", "Drilled metres and elapsed days, which are the only two totals the cost side is ever handed.", "Elapsed days for both, since every line on an authorisation for expenditure is ultimately billed against the calendar."]'::jsonb, 2, 'There is no fourth basis and so no fourth quantity, and total depth never crosses that boundary even where it equals drilled metres.'),
  ('wellcost', 'beginner', 'final', null, 35, 'How many rows of the golden schedule do you need before more than half of the 432 elapsed hours is accounted for?', '["Six, since the schedule is fairly evenly spread.", "Two, since the pair of 112.5 hour drill rows comes to 225 hours, already past half of the clock.", "Ten, because the allowance is spread across every row and no subset of rows can reach half of the elapsed clock.", "Three, once the 67.5 hour completion is added to the two drill rows."]'::jsonb, 1, 'Sorting by duration and reading the top of the list is the second step in the order of attack, after the two end identities.'),
  ('wellcost', 'beginner', 'final', null, 36, 'A handed-over line carries one depth, a running speed and a term in hours that no speed can affect. Which kind is it and how is it priced?', '["A trip, whose hours are twice the depth over the speed.", "A drill activity, with the hours standing in place of a rate of penetration.", "A casing run, whose hours are the depth over the run speed with the flat term added on top of that.", "Flat work, because a stated number of hours on the line settles the classification whatever else it happens to carry."]'::jsonb, 2, 'Step one of the method labels by the fields a line is given, and only step two reaches for a formula.'),
  ('wellcost', 'beginner', 'final', null, 37, 'An estimate arrives stating 384 productive hours, 48 non-productive hours and 20 elapsed days. What should the reviewer say?', '["The three numbers do not reconcile, because 384 and 48 make 432 hours, which is 18 days rather than 20.", "The split should not have been quoted beside the day count at all.", "Nothing, since days are reported as decimals.", "The non-productive figure must be wrong, because the allowance is recomputed from the day count once a schedule is rolled up."]'::jsonb, 0, 'That identity is the first of the two end checks, and a mismatch means the schedule was edited without being evaluated again.'),
  ('wellcost', 'beginner', 'final', null, 38, 'The well finishes three days late but still reaches the planned total depth. Which of the three cost bases feels that?', '["All three, since the whole estimate scales with the schedule.", "The lump lines only, since they have no quantity to protect them.", "The per-metre lines only, because those metres were bought over a longer period and the rate is quoted against the calendar.", "The per-day lines only, whose sensitivity to elapsed days is 1.0 against 0.0 for each of the other two."]'::jsonb, 3, 'On the golden estimate 53.53 percent of the base is per-day exposed, and deepening a well without slipping is the mirror case.'),
  ('wellcost', 'beginner', 'final', null, 39, 'A team adopts the 16 day figure that the golden programme returns at a zero allowance and calls it the plan. What have they assumed?', '["That the rig will be released two days early.", "That nothing whatever goes wrong, since 16 days is the work itself with no trouble time added on top.", "That the allowance is carried separately in the contingency, which is where a zero fraction moves the trouble hours to.", "That the productive hours have come down along with the elapsed hours."]'::jsonb, 1, 'The programme that actually finishes is the 432 hour one, so a rig slot promised on 384 hours is two days short before spud.'),
  ('wellcost', 'beginner', 'final', null, 40, 'Both the trip rows and the casing rows of a submitted schedule are understated. Which pair of habitual slips would produce that?', '["Both kinds were entered at the wrong depth.", "The trip speed and the run speed were swapped between the two kinds.", "The allowance was applied to the drill rows alone, leaving every other kind sitting at its unstretched productive hours.", "The factor of two dropped from the trips, and the flat term omitted from the casing runs."]'::jsonb, 3, 'Forgetting the two halves a trip, and at realistic running speeds the flat term is the larger part of a casing job.'),
  ('wellcost', 'beginner', 'final', null, 41, 'A superintendent and a finance manager each want one output from the same evaluation. What goes to each of them?', '["The authorisation for expenditure to both, since it carries the day count.", "The schedule with its split to the superintendent, and the day count with the drilled metres to finance.", "The cost time curve to both, because it is the only output holding hours and money in one picture and it needs no explaining.", "The risked percentiles to the superintendent and the base case to finance."]'::jsonb, 1, 'The split is what makes 18 days challengeable, and once it has been converted the day count is only a multiplier.'),
  ('wellcost', 'beginner', 'final', null, 42, 'Waiting on weather is entered as a flat activity and the allowance is then raised to cover weather as well. What is wrong?', '["Nothing, since weather is genuinely uncertain.", "Weather cannot be a flat activity, as it advances the well by nothing.", "The flat activity is ignored, because the allowance takes precedence over any duration a user has stated by hand.", "The same hours are counted twice, once as planned work and once again inside the stretch laid on top."]'::jsonb, 3, 'Time you can name in advance belongs in the list and time you cannot belongs in the fraction, and there are only those two homes.');
